#ifndef PILA_H
#define PILA_H

#define MAX 8

typedef enum {
  FALSO,
  VERDADERO
} TBool;

typedef struct {
  int datos[MAX];
  int tope;
} TPila;

void inicializar(TPila *p);
void apilar(TPila *p, int x);
int desapilar(TPila *p);
int cima(TPila p);
TBool vacia(TPila p);
TBool llena(TPila p);

#endif

#include "pila.h"

void inicializar(TPila *p) {
  p->tope = 0;
}

void apilar(TPila *p, int x) {
  p->datos[p->tope] = x;
  p->tope = p->tope + 1;
}

int desapilar(TPila *p) {
  p->tope = p->tope - 1;
  return p->datos[p->tope];
}

int cima(TPila p) {
  return p.datos[p.tope - 1];
}

TBool vacia(TPila p) {
  if (p.tope == 0) {
    return VERDADERO;
  }
  return FALSO;
}

TBool llena(TPila p) {
  if (p.tope == MAX) {
    return VERDADERO;
  }
  return FALSO;
}

#include <stdio.h>
#include "pila.h"

int main() {
  TPila p;

  inicializar(&p);
  apilar(&p, 1);
  apilar(&p, 2);
  apilar(&p, 3);
  while (!vacia(p)) {
    printf("%d ", desapilar(&p));
  }
  return 0;
}

