void inicializar(TPila *p) {
  p->tope = -1;
}

void apilar(TPila *p, int x) {
  p->tope = p->tope + 1;
  p->datos[p->tope] = x;
}

int desapilar(TPila *p) {
  int x;

  x = p->datos[p->tope];
  p->tope = p->tope - 1;
  return x;
}

int cima(TPila p) {
  return p.datos[p.tope];
}

TBool vacia(TPila p) {
  if (p.tope == -1) {
    return VERDADERO;
  }
  return FALSO;
}

TBool llena(TPila p) {
  if (p.tope == MAX - 1) {
    return VERDADERO;
  }
  return FALSO;
}
